INSERT OR REPLACE INTO controversy_topics (id, topic, slug, category, rating, summary, positions, keywords, sources, note, source) VALUES (1, 'Date of the Exodus', 'date-of-the-exodus', 'dating', 'high', 'Scholars dispute when the Israelite Exodus from Egypt occurred, with the two main proposals separated by roughly 200 years. The early (15th-century BCE) date is inferred from a literal reading of 1 Kings 6:1, while the late (13th-century BCE) date correlates with Egyptian archaeological evidence from the Ramesside period. Neither position commands consensus, and each faces unresolved exegetical and archaeological difficulties.', '[{"label":"Early (15th-century BCE) date","view":"The Exodus occurred ca. 1446 BCE, anchored by the 480-year figure in 1 Kings 6:1 and corroborated by Judges 11:26, which implies roughly 300 years of Israelite settlement prior to Jephthah.","evidence":"1 Kings 6:1 places the Exodus 480 years before Solomon''s fourth regnal year (ca. 966 BCE), yielding ca. 1446 BCE. Judges 11:26 independently implies a long pre-monarchic settlement period. Proponents argue that the city Avaris (Tell el-Dab''a) shows a Semitic population presence during the Middle Bronze Age consistent with an earlier sojourn. Some correlate the Amarna letters with the period of Israelite conquest.","scholars":["Bryant Wood","John Bimson","Andrew Steinmann","Charles Aling"]},{"label":"Late (13th-century BCE) date","view":"The Exodus occurred ca. 1260–1250 BCE under Ramesses II (or near his reign), based on the reference to the store-city Raamses in Exodus 1:11 and the flourishing of Ramesside building projects in the eastern Delta during this period.","evidence":"Exodus 1:11 names Raamses as a store-city built by Israelite labor, widely identified with Pi-Ramesse, a major city under Ramesses II (1279–1213 BCE). The Merneptah Stele (ca. 1208 BCE) attests Israel as a people in Canaan, setting a terminus ante quem. The absence of clear Mycenaean Late Bronze Age destructions matching a 15th-century conquest at key Canaanite sites also weighs against the early date.","scholars":["Kenneth Kitchen","James Hoffmeier","Alan Millard","Manfred Bietak (on Avaris)"]}]', '["exodus","exodus date","early date","late date","15th century","13th century","Ramesside","1 Kings 6:1","Judges 11:26","Amarna","Merneptah stele"]', '[{"citation":"Kitchen, K. A. On the Reliability of the Old Testament. Grand Rapids: Eerdmans, 2003.","tier":"A"},{"citation":"Hoffmeier, J. K. Israel in Egypt: The Evidence for the Authenticity of the Exodus Tradition. Oxford: Oxford University Press, 1997.","tier":"A"},{"citation":"Bimson, J. J. Redating the Exodus and Conquest. Sheffield: JSOT Press, 1978.","tier":"A"},{"citation":"Wood, B. G. \"The Sons of Jacob: New Evidence for the Presence of the Israelites in Egypt.\" Biblical Archaeology Review 34.2 (2008).","tier":"B"}]', NULL, 'curated-in-house');
