INSERT OR REPLACE INTO controversy_topics (id, topic, slug, category, rating, summary, positions, keywords, sources, note, source) VALUES (2, 'Authorship and dating of Daniel', 'authorship-and-dating-of-daniel', 'authorship', 'high', 'Scholars are divided over whether the book of Daniel was composed by a single author in the 6th century BCE (the traditional view) or by one or more authors writing in the 2nd century BCE during the Maccabean crisis. The dispute turns on the interpretation of detailed prophecy in chapters 7–12, the linguistic character of the Aramaic and Hebrew sections, and historical details in chapter 1 and 5. Both positions have substantial scholarly representation.', '[{"label":"Traditional 6th-century single-author view","view":"Daniel the Jew wrote the book in Babylon during the 6th century BCE under Nebuchadnezzar, Belshazzar, and Darius the Mede, and the detailed predictions of chapters 7–12 are genuine predictive prophecy.","evidence":"The book presents itself as first-person testimony from the 6th century (Dan 1:1; 7:1). Jesus cites Daniel as prophetic (Matt 24:15). Dead Sea Scroll manuscripts of Daniel predate the Maccabean period sufficiently to suggest a pre-2nd century composition. The early Old Greek translation implies circulation well before 165 BCE. Proponents argue that \"Darius the Mede\" is a historical figure whose identity has not yet been definitively resolved, and that \"vaticinium ex eventu\" arguments depend on a prior commitment against predictive prophecy.","scholars":["Joyce Baldwin","Stephen Miller","Gleason Archer"]},{"label":"Maccabean 2nd-century pseudepigraphical view","view":"The book of Daniel reached its final form in the 160s BCE, composed pseudepigraphically to encourage Jews facing the persecution of Antiochus IV Epiphanes, with chapters 7–12 describing those events as if predicted from the 6th century.","evidence":"Daniel 11:2–35 tracks Hellenistic history with extraordinary accuracy up to Antiochus IV, then becomes vague at 11:40, suggesting the author''s horizon. Linguistic analysis finds late Biblical Hebrew forms and an Aramaic dialect consistent with the 3rd–2nd century. The absence of Daniel from Ben Sira''s \"Praise of the Fathers\" (ca. 180 BCE) is cited as evidence the book was not yet widely known. The genre of pseudepigraphical apocalyptic has close parallels in 2nd-century Jewish literature.","scholars":["John J. Collins","Louis Hartman","Klaus Koch","Norman Porteous"]}]', '["Daniel","authorship","vaticinium ex eventu","Maccabean","6th century","2nd century","Antiochus Epiphanes","Daniel 11","Aramaic","apocalyptic","single authorship"]', '[{"citation":"Baldwin, J. G. Daniel: An Introduction and Commentary. Tyndale Old Testament Commentaries. Leicester: IVP, 1978.","tier":"B"},{"citation":"Collins, J. J. Daniel: A Commentary on the Book of Daniel. Hermeneia. Minneapolis: Fortress, 1993.","tier":"A"},{"citation":"Miller, S. R. Daniel. New American Commentary. Nashville: Broadman & Holman, 1994.","tier":"B"},{"citation":"Goldingay, J. Daniel. Word Biblical Commentary 30. Dallas: Word Books, 1989.","tier":"A"}]', NULL, 'curated-in-house');
